import{_ as e,o as t,c as r,a2 as l}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"Keynote: Ceph as Part of the Data Infrastructure for Zoned Storage - Jorge Campello De Souza","description":"","frontmatter":{"title":"Keynote: Ceph as Part of the Data Infrastructure for Zoned Storage - Jorge Campello De Souza","date":"2019-05-24T00:00:00.000Z","updated":"2019-05-24T00:00:00.000Z","tags":["Ceph","Zoned Storage","Data Infrastructure","SMR Technology","Storage Efficiency"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/Keynote_-_Ceph_as_Part_of_the_Data_Infrastructure_for_Zoned_Storage_-_Jorge_Campello_De_Souza.md","filePath":"posts/2019/Keynote_-_Ceph_as_Part_of_the_Data_Infrastructure_for_Zoned_Storage_-_Jorge_Campello_De_Souza.md","lastUpdated":1780459816000}'),n={name:"posts/2019/Keynote_-_Ceph_as_Part_of_the_Data_Infrastructure_for_Zoned_Storage_-_Jorge_Campello_De_Souza.md"};function a(_,o,s,i,g,p){return t(),r("div",null,[...o[0]||(o[0]=[l("<p>会议纪要</p><p><strong>会议时间</strong>： 2023年[具体日期]</p><p><strong>会议地点</strong>： [具体地点]</p><p><strong>参会人员</strong>： [参会人员名单]</p><p><strong>会议主题</strong>： Saif项目作为Zone存储数据基础设施的一部分</p><p><strong>会议内容</strong>：</p><ul><li><strong>开场</strong>： 会议以互动方式开始，主持人介绍了Saif项目作为数据基础设施的一部分，并强调了数据驱动经济对数据基础设施带来的压力。</li><li><strong>数据驱动经济的影响</strong>： 会议指出，数据驱动经济下的新技术（如人工智能、机器学习等）导致数据量激增，对数据基础设施提出了更高的要求。</li><li><strong>存储技术转型</strong>： 主持人介绍了存储技术的转型，特别是SMR（单磁记录）技术在硬盘驱动器中的应用，以及SSD中擦除块的约束。</li><li><strong>Zone Block Devices</strong>： 详细解释了Zone Block Devices的工作原理，包括线性地址空间、区域划分、顺序写入等特性，以及其带来的性能和效率提升。</li><li><strong>SEF与Zone Block Technologies</strong>： 讨论了如何将Zone Block Technologies整合到SEF（Sage）项目中，以利用这些新技术提高存储效率。提到与CMU（卡内基梅隆大学）的合作，共同推进相关研究。</li><li><strong>行动计划</strong>： 鼓励参会人员进一步了解这些新技术，并参与到相关研究和项目中。</li></ul><p><strong>关键细节</strong>：</p><ul><li>数据驱动经济对数据基础设施带来的压力。</li><li>SMR技术在硬盘驱动器中的应用。</li><li>Zone Block Devices的特性及其优势。</li><li>SEF与Zone Block Technologies的整合。</li><li>与CMU的合作。</li></ul><p><strong>讨论的主要议题</strong>：</p><ul><li>如何应对数据驱动经济带来的挑战。</li><li>如何利用新技术提高存储效率。</li><li>如何将Zone Block Technologies整合到SEF项目中。</li><li>Ceph在Zoned Storage中的角色。</li></ul><p><strong>决定的事项</strong>：</p><ul><li>推进SEF与Zone Block Technologies的整合。</li><li>加强与CMU等机构的合作。</li><li>鼓励参会人员参与相关研究和项目。</li></ul><p><strong>后续行动计划</strong>：</p><ul><li>与CMU等机构合作，推进Zone Block Technologies的研究。</li><li>将研究成果应用到SEF项目中。</li><li>加强与社区的合作，共同推动存储技术的发展。</li></ul>",15)])])}const S=e(n,[["render",a]]);export{u as __pageData,S as default};
